23	class ForceZeroTester extends Module {
24	  val io = IO(new Bundle {
25	    val in  = Input(Valid(SInt(32.W)))
26	    val out = Output(Valid(SInt(32.W)))
27	  })
28	
29	  io.out := ForceZero(io.in)
30	}
